import{_ as t,C as i,o as a,c as s,a3 as n,E as d}from"./chunks/framework.BZKbe9n2.js";const _=JSON.parse('{"title":"Tags bearbeiten","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/editing.md","filePath":"de/guide/editing.md"}'),l={name:"de/guide/editing.md"};function o(g,e,u,b,h,m){const r=i("Screenshot");return a(),s("div",null,[e[0]||(e[0]=n('<h1 id="tags-bearbeiten" tabindex="-1">Tags bearbeiten <a class="header-anchor" href="#tags-bearbeiten" aria-label="Permalink to &quot;Tags bearbeiten&quot;">​</a></h1><p>Redaktion und Administratoren können die Angaben der Bibliothek berichtigen: Titel, Künstler, Alben, Jahre, Genres, Komponisten und mehr.</p><h2 id="bearbeitungsansicht" tabindex="-1">Bearbeitungsansicht <a class="header-anchor" href="#bearbeitungsansicht" aria-label="Permalink to &quot;Bearbeitungsansicht&quot;">​</a></h2><p>Stelle die <strong>Ansicht</strong> von <strong>Hören</strong> auf <strong>Editieren</strong>. Titel erhalten Kontrollkästchen; wähle die Titel aus, die du ändern willst, oder <strong>Alle auswählen</strong>, und wähle <strong>Tags bearbeiten</strong>. Auf einer Albumseite bearbeitet <strong>Album bearbeiten</strong> das Album selbst.</p>',4)),d(r,{name:"tag-editor",alt:"Der Tag-Editor für ein Album"}),e[1]||(e[1]=n('<ul><li>Ein Feld mit <strong>verschiedenen Werten</strong> unter den gewählten Titeln bleibt unverändert, ausser du gibst einen Wert ein.</li><li>Trenne mehrere Werte (zum Beispiel Genres) mit Kommas.</li><li><strong>Titel in diesem Album</strong> und <strong>Künstler in diesem Album</strong> ändern nur, wie ein Titel auf diesem Album erscheint; die Aufnahme behält ihren eigenen Titel.</li></ul><p>Jedes Feld wird dort gespeichert, wo es hingehört: der Titel einer Aufnahme einmal für alle Alben, auf denen sie vorkommt, das Jahr eines Albums einmal für das Album. <strong>Tags übernehmen</strong> speichert die Änderung; grosse Änderungen laufen im Hintergrund.</p><p>Aus der Suche bearbeitet <strong>Alle Ergebnisse bearbeiten</strong> alle Ergebnisse auf einmal.</p><h2 id="ruckgangig-und-verlauf" tabindex="-1">Rückgängig und Verlauf <a class="header-anchor" href="#ruckgangig-und-verlauf" aria-label="Permalink to &quot;Rückgängig und Verlauf&quot;">​</a></h2><p>Der <strong>Änderungsverlauf</strong> listet jede Änderung mit Person und Zeitpunkt. Jede Änderung lässt sich rückgängig machen; Felder, die seither erneut geändert wurden, bleiben, wie sie sind, und werden gemeldet.</p><h2 id="tags-in-den-dateien" tabindex="-1">Tags in den Dateien <a class="header-anchor" href="#tags-in-den-dateien" aria-label="Permalink to &quot;Tags in den Dateien&quot;">​</a></h2><p>Anthology hält die Angaben in seiner Datenbank und schreibt sie in die Dateien, die es verwaltet. Dateien, die in ihrem Ordner bleiben (referenziert), werden nur beschrieben, wenn das beim Import erlaubt wurde. Downloads und die Musik für die Lautsprecher tragen immer die Tags ihres Albums.</p>',7))])}const p=t(l,[["render",o]]);export{_ as __pageData,p as default};
